var nomesAtivos = usuarios
    .Where(u => u.Ativo && u.Idade >= 18)
    .OrderBy(u => u.Nome)
    .Select(u => u.Nome.ToUpper())
    .ToList();

bool temAdmin = usuarios.Any(u => u.Role == "ADMIN");
var primeiro = usuarios.FirstOrDefault(u => u.Id == 10);

